// Explications originales pour relier l’anatomie aux gestes en salle.
// Un exercice implique plusieurs muscles ; ces exemples ne sont pas des prescriptions.
const rows=[
['deltoid','Élever le bras. L’avant aide à le lever devant soi, le milieu sur le côté, l’arrière à le ramener en arrière.','Élévation latérale','La portion moyenne participe à la montée du bras et freine sa descente.','Trois portions, trois orientations : ne pas attribuer la même action à tout le deltoïde.','Clavicule et omoplate (acromion et épine).','Face externe de l’humérus, l’os du bras.'],
['biceps_brachii','Plier le coude et tourner la paume vers le haut.','Curl avec haltères','Il aide à monter la charge ; pendant une descente contrôlée, il freine l’ouverture du coude.','Le biceps ne fait pas que plier le bras : pense aussi à la supination, paume vers le haut.','Omoplate : au-dessus de l’articulation et sur le processus coracoïde.','Radius, un des deux os de l’avant-bras.'],
['triceps','Déplier le coude. Son chef long aide aussi à ramener le bras en arrière.','Extension de coude à la poulie','Il participe à l’extension du coude. Il intervient aussi dans les pompes et les développés.','Trois chefs ; seul le chef long traverse aussi l’épaule.','Omoplate pour le chef long ; humérus pour les deux autres.','Pointe du coude : olécrâne de l’ulna.'],
['brachialis','Plier le coude, que la paume regarde vers le haut, le bas ou le côté.','Curl en prise neutre','Il contribue à la flexion du coude avec les autres fléchisseurs, sous le biceps.','Attaché à l’ulna : il ne tourne pas l’avant-bras.','Face avant de la moitié basse de l’humérus.','Partie haute de l’ulna, sous le coude.'],
['brachioradialis_muscle','Plier le coude, particulièrement avec le pouce vers le haut.','Curl marteau','Il participe au mouvement lorsque l’avant-bras est en position intermédiaire.','Un muscle du côté de l’avant-bras peut agir au coude.','Bord externe du bas de l’humérus.','Radius, près du poignet.'],
['pectoralis_major','Ramener le bras vers le corps et vers l’avant, et le tourner vers l’intérieur.','Pompe ou développé couché','Il rapproche le bras devant la poitrine pendant la poussée, avec le deltoïde antérieur et le triceps.','Il agit sur l’épaule ; c’est le triceps qui déplie le coude.','Clavicule, sternum et cartilages des côtes.','Partie haute de l’humérus.'],
['latissimus_dorsi','Ramener le bras vers le bas, près du corps et vers l’arrière.','Tirage vertical','Il participe à la descente du bras depuis une position élevée. Les fléchisseurs du coude contribuent aussi au tirage.','Le grand dorsal déplace le bras à l’épaule, il ne fléchit pas directement le coude.','Bas du dos, fascia thoracolombaire, bassin et dernières côtes.','Partie haute de l’humérus.'],
['trapezius','Déplacer et orienter l’omoplate : la hausser, la rapprocher de la colonne ou l’abaisser selon ses faisceaux.','Shrug / élévation du bras','Le shrug sollicite les faisceaux supérieurs. Lever le bras mobilise aussi la rotation de l’omoplate.','La rotation vers le haut associe trapèze supérieur, trapèze inférieur et dentelé antérieur.','Arrière du crâne, nuque et colonne jusqu’au bas du thorax.','Clavicule et reliefs de l’omoplate.'],
['serratus_anterior','Faire glisser l’omoplate vers l’avant et la maintenir contre les côtes.','Pompe plus','La poussée supplémentaire en fin de pompe écarte les omoplates autour du thorax.','Stabiliser l’omoplate ne veut pas dire la garder immobile.','Faces latérales des premières côtes.','Face de l’omoplate tournée vers les côtes, le long de son bord interne.'],
['rhomboid_major','Rapprocher l’omoplate de la colonne et contribuer à son maintien.','Tirage horizontal','Il participe au rapprochement des omoplates, avec d’autres muscles du dos.','Le grand rhomboïde est sous le trapèze ; il agit sur l’omoplate, pas directement sur le bras.','Colonne thoracique, vertèbres T2 à T5.','Bord interne de l’omoplate, sous son épine.'],
['rhomboid_minor','Rapprocher l’omoplate de la colonne et la stabiliser.','Tirage horizontal','Il coopère avec le grand rhomboïde pendant le contrôle de l’omoplate.','Plus haut et plus petit que le grand rhomboïde.','Base du cou : C7 à T1 et ligament nuchal.','Bord interne de l’omoplate, à la base de son épine.'],
['supraspinatus','Aider à lever le bras sur le côté et à centrer la tête de l’humérus.','Élévation du bras dans le plan de l’omoplate','Il travaille avec le deltoïde et les autres muscles qui stabilisent l’épaule.','Coiffe des rotateurs : mouvement et stabilité vont ensemble.','Dessus de l’épine de l’omoplate.','Sommet du tubercule majeur de l’humérus.'],
['infraspinatus','Tourner le bras vers l’extérieur et stabiliser l’épaule.','Rotation externe avec élastique','Coude près du corps, il participe au déplacement de l’avant-bras vers l’extérieur par rotation du bras.','Le mouvement se passe à l’épaule, même si la main se déplace.','Arrière de l’omoplate, sous son épine.','Tubercule majeur de l’humérus.'],
['teres_minor','Tourner le bras vers l’extérieur et stabiliser l’épaule.','Rotation externe avec élastique','Il coopère avec l’infra-épineux pendant la rotation externe.','Petit rond = coiffe des rotateurs ; grand rond = autre groupe.','Bord externe de l’omoplate.','Tubercule majeur de l’humérus.'],
['subscapularis','Tourner le bras vers l’intérieur et stabiliser l’épaule.','Rotation interne avec élastique','Il participe à la rotation interne avec plusieurs muscles plus volumineux.','C’est le muscle de la coiffe situé sur la face avant de l’omoplate.','Face de l’omoplate contre le thorax.','Tubercule mineur de l’humérus.'],
['rectus_abdominis','Rapprocher le thorax du bassin en fléchissant le tronc.','Crunch / gainage ventral','Au crunch, il participe à la flexion du tronc. En gainage, il aide à résister à son extension.','Un muscle peut produire un mouvement ou empêcher ce mouvement de se produire.','Pubis, à l’avant du bassin.','Bas du sternum et cartilages des côtes 5 à 7.'],
['external_oblique','Faire tourner le tronc vers le côté opposé et aider à contrôler l’abdomen.','Rotation à la poulie','Il participe à la rotation et, selon la tâche, au freinage ou à la résistance à la rotation.','Oblique externe droit : rotation du tronc vers la gauche.','Faces externes des côtes 5 à 12.','Ligne centrale de l’abdomen, bassin et pubis.'],
['internal_oblique','Faire tourner le tronc du même côté et aider à contrôler l’abdomen.','Rotation à la poulie','Il coopère avec l’oblique externe du côté opposé pour la rotation.','Oblique interne droit : rotation du tronc vers la droite.','Bassin, fascia du bas du dos et ligament inguinal.','Dernières côtes, ligne centrale de l’abdomen et pubis.'],
['transversus_abdominis','Mettre la paroi abdominale en tension et contribuer au contrôle du tronc.','Gainage / port de charge','Il participe au maintien de la paroi abdominale avec les autres muscles du tronc.','Ses fibres sont plutôt horizontales ; ne pas le confondre avec le muscle du crunch.','Côtes inférieures, fascia du dos, bassin et ligament inguinal.','Ligne centrale de l’abdomen et pubis.'],
['gluteus_maximus','Ramener la cuisse en arrière et redresser la hanche.','Hip thrust / remontée d’un squat','Il participe à l’extension de hanche et au contrôle du bassin avec les autres extenseurs.','Grand fessier = puissant extenseur de hanche, surtout depuis une position fléchie.','Arrière du bassin, sacrum, coccyx et ligament sacrotubéral.','Fémur et tractus iliotibial, sur le côté de la cuisse.'],
['gluteus_medius','Écarter la cuisse et garder le bassin stable sur une jambe.','Appui unipodal / montée de marche','Il contribue au contrôle du bassin pendant l’appui sur une seule jambe.','Sa fonction ne se limite pas aux abductions sur machine.','Face externe de l’os du bassin.','Grand trochanter, relief externe du haut du fémur.'],
['gluteus_minimus','Écarter la cuisse, aider à la tourner vers l’intérieur et stabiliser le bassin.','Appui unipodal','Il coopère avec le moyen fessier, plus superficiel.','Petit fessier = profond au moyen fessier.','Face externe de l’os du bassin, sous le moyen fessier.','Face avant du grand trochanter.'],
['rectus_femoris','Tendre le genou et lever la cuisse devant soi.','Leg extension','Il participe à l’extension du genou avec les trois vastes ; sa longueur dépend aussi de la position de la hanche.','Seul chef du quadriceps à traverser hanche ET genou.','Avant du bassin, au-dessus de l’articulation de hanche.','Patella, puis tibia par le tendon quadricipital et le ligament patellaire.'],
['vastus_lateralis','Tendre le genou depuis la partie externe de la cuisse.','Squat / leg extension','Il participe à la poussée qui déplie le genou et freine la flexion lors d’une descente contrôlée.','Un des trois vastes : il traverse le genou, pas la hanche.','Face externe du fémur et ligne âpre.','Patella, puis tubérosité du tibia.'],
['vastus_medialis','Tendre le genou et participer à la stabilité de la rotule du côté interne.','Squat / leg extension','Il travaille avec le reste du quadriceps ; un exercice ne l’isole pas complètement.','Repère : relief interne au-dessus du genou.','Fémur, le long de son bord interne et de la ligne âpre.','Patella, puis tubérosité du tibia.'],
['vastus_intermedius','Tendre le genou depuis le plan profond de la cuisse.','Leg extension','Il contribue à l’extension avec les autres chefs du quadriceps.','Il est caché sous le droit fémoral.','Faces avant et latérale du fémur.','Patella, puis tubérosité du tibia.'],
['biceps_femoris','Plier le genou et tourner la jambe fléchie vers l’extérieur. Le chef long aide à étendre la hanche.','Leg curl / charnière de hanche','Au leg curl, les deux chefs participent à la flexion du genou. En charnière de hanche, le chef long est concerné par l’action à la hanche.','Ischio-jambier externe ; le chef court ne traverse pas la hanche.','Ischion pour le chef long ; fémur pour le chef court.','Tête de la fibula, sous le côté externe du genou.'],
['semitendinosus','Plier le genou, étendre la hanche et tourner la jambe fléchie vers l’intérieur.','Leg curl / soulevé de terre roumain','Il participe au travail des ischio-jambiers aux deux articulations.','Ischio-jambier médial avec un long tendon distal.','Ischion, en bas du bassin.','Face interne du haut du tibia, à la patte d’oie.'],
['semimembranosus','Plier le genou, étendre la hanche et tourner la jambe fléchie vers l’intérieur.','Leg curl / soulevé de terre roumain','Il coopère avec le semi-tendineux et le chef long du biceps fémoral.','Ischio-jambier médial à large tendon d’origine.','Ischion, en bas du bassin.','Arrière du condyle médial du tibia.'],
['gastrocnemius','Pousser sur l’avant-pied et aider à plier le genou.','Élévation des mollets debout','Il participe à la montée du talon. Genou fléchi, son rôle relatif change car il traverse aussi le genou.','Gastrocnémien = deux articulations : genou et cheville.','Arrière du bas du fémur, au-dessus du genou.','Calcanéus par le tendon d’Achille (tendon calcanéen).'],
['soleus','Pousser sur l’avant-pied et aider à tenir debout.','Élévation des mollets assis','Il participe à la flexion plantaire même lorsque le genou est fléchi.','Soléaire = cheville seulement ; il ne traverse pas le genou.','Tibia et fibula, à l’arrière de la jambe.','Calcanéus par le tendon d’Achille.'],
['tibialis_anterior','Relever l’avant du pied et orienter sa plante vers l’intérieur.','Relevé de pointes de pieds','Il relève l’avant-pied et participe à son contrôle pendant la marche.','Ne pas confondre relever les orteils et monter sur la pointe des pieds.','Face externe du tibia et membrane entre tibia et fibula.','Bord interne du pied : cunéiforme médial et premier métatarsien.'],
['fibularis_longus','Orienter la plante du pied vers l’extérieur et aider à pousser sur l’avant-pied.','Éversion contre élastique','Il participe au contrôle latéral de la cheville avec le court fibulaire.','Son tendon passe derrière la malléole externe, puis sous le pied.','Face externe du haut de la fibula.','Sous le pied : premier métatarsien et cunéiforme médial.'],
['adductor_longus','Rapprocher la cuisse de l’axe du corps et aider à fléchir la hanche.','Adduction à la poulie','Il ramène la cuisse vers l’intérieur avec les autres adducteurs.','Adduction = rapprocher ; abduction = éloigner.','Pubis, à l’avant du bassin.','Ligne âpre, sur le fémur.'],
['adductor_magnus','Rapprocher la cuisse du corps. Sa partie postérieure aide à étendre la hanche.','Adduction / remontée de squat','Ses différentes portions contribuent différemment aux mouvements de hanche.','Le grand adducteur n’est pas seulement un muscle qui serre les jambes.','Pubis et ischion.','Arrière du fémur et tubercule de l’adducteur, près du genou.'],
['iliacus','Lever la cuisse devant soi, avec le grand psoas.','Flexion de hanche contre résistance','Il participe à la flexion de hanche ; il ne faut pas confondre ce mouvement avec une flexion du tronc.','Iliaque + grand psoas = iliopsoas.','Face interne du bassin : fosse iliaque.','Petit trochanter du fémur.'],
['psoas_major','Lever la cuisse et contribuer au contrôle de la région lombaire.','Flexion de hanche contre résistance','Il relie le rachis au fémur et participe à la flexion de hanche avec l’iliaque.','Il traverse la hanche ; sa relation avec les lombaires explique qu’il ne soit pas qu’un simple muscle de cuisse.','Vertèbres de la région T12 à L5.','Petit trochanter du fémur.'],
['tensor_fasciae_latae','Lever et écarter la cuisse, tout en mettant en tension la bande latérale de la cuisse.','Abduction de hanche','Il contribue au mouvement avec les fessiers ; il ne faut pas attribuer toute abduction au seul moyen fessier.','Le tractus iliotibial transmet sa tension vers le genou.','Avant de la crête iliaque, sur le bassin.','Tractus iliotibial, puis tibia par cette bande fibreuse.'],
['quadratus_lumborum','Incliner le tronc sur le côté et contribuer à sa stabilité.','Port de charge à une main','Il participe à la résistance à l’inclinaison latérale avec d’autres muscles du tronc.','En statique, un muscle peut travailler sans produire de mouvement visible.','Crête du bassin et ligament iliolombaire.','Douzième côte et vertèbres lombaires.'],
['abductor_hallucis','Écarter le gros orteil et aider à soutenir l’arche interne du pied.','Contrôle du pied en appui','Il participe au soutien actif du pied avec les autres muscles intrinsèques.','Dans le pied, l’axe de référence des orteils passe par le deuxième orteil.','Calcanéus et tissus fibreux de la plante.','Base de la première phalange du gros orteil, côté interne.'],
];
export const coachProfiles=Object.fromEntries(rows.map(([id,plain,exercise,gym,remember,originSimple,insertionSimple])=>[id,{plain,exercise,gym,remember,originSimple,insertionSimple}]));
const translations=[[/métacarpophalangiennes?/gi,'articulations à la base des doigts'],[/interphalangiennes?/gi,'articulations entre les phalanges'],[/métatarsophalangiennes?/gi,'articulations à la base des orteils'],[/homolatérale/gi,'du même côté'],[/controlatérale/gi,'du côté opposé'],[/dorsiflexion/gi,'relèvement de l’avant-pied'],[/flexion plantaire/gi,'poussée du pied vers le bas'],[/rotation latérale/gi,'rotation vers l’extérieur'],[/rotation médiale/gi,'rotation vers l’intérieur'],[/scapula/gi,'omoplate'],[/glénohumérale/gi,'de l’épaule'],[/hallux/gi,'gros orteil'],[/protraction/gi,'déplacement vers l’avant'],[/rétraction/gi,'rapprochement vers la colonne']];
export function plainLanguage(text){return translations.reduce((s,[pattern,value])=>s.replace(pattern,value),text);}
export function coachFor(l){if(!l)return null;return coachProfiles[l.id]||{plain:plainLanguage(l.action),exercise:null,gym:'Repérez l’articulation concernée et le mouvement décrit. Le rôle du muscle dépend de la tâche : produire un mouvement, le freiner ou stabiliser une position.',remember:null,originSimple:null,insertionSimple:null};}
export const movementGlossary=[['Flexion / extension','Fermer / ouvrir l’angle d’une articulation.'],['Abduction / adduction','Éloigner / rapprocher un segment de l’axe de référence.'],['Supination / pronation','Tourner l’avant-bras : paume vers le haut / vers le bas, coude fléchi.'],['Concentrique','Le muscle produit de la tension en se raccourcissant.'],['Excentrique','Le muscle produit de la tension en s’allongeant, par exemple pour freiner une descente.'],['Isométrique','Le muscle produit de la tension sans changement notable de longueur à l’échelle du mouvement.']];
